"""Run sql/02_analysis.sql against data/anadolu_home.db and write docs/05-analysis-results.md."""
import re
import sqlite3
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
con = sqlite3.connect(ROOT / "data" / "anadolu_home.db")
sql = (ROOT / "sql" / "02_analysis.sql").read_text(encoding="utf-8")

blocks = re.split(r"^-- name: ", sql, flags=re.M)[1:]
out = ["# 05 - Analysis Results",
       "",
       "> Auto-generated by `scripts/run_analysis.py` from the **synthetic** dataset. "
       "Re-run it to reproduce every number below.",
       ""]
for b in blocks:
    head, _, body = b.partition("\n")
    _, title = [s.strip() for s in head.split("|", 1)]
    cur = con.execute(body)
    cols = [d[0] for d in cur.description]
    rows = cur.fetchall()
    out += [f"## {title}", "", "```sql", body.strip(), "```", "",
            "| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    out += ["| " + " | ".join("" if v is None else str(v) for v in r) + " |" for r in rows]
    out.append("")
(ROOT / "docs" / "05-analysis-results.md").write_text("\n".join(out), encoding="utf-8")
print("written docs/05-analysis-results.md")
